def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    if n == 1:
        return 'C'
    if n == 2:
        return 'C' if opp[-1] == 'C' else 'D'
    if n < 5:
        return 'C' if opp[-1] == 'C' else 'D'
    opp_c = sum(1 for x in opp if x == 'C')
    opp_d = n - opp_c
    recent = opp[-5:]
    rec_c = sum(1 for x in recent if x == 'C')
    if opp_d == 0:
        return 'C'
    if opp_c == 0:
        return 'D'
    if rec_c >= 4:
        return 'C'
    if rec_c <= 1:
        return 'D'
    last_me = me[-1]
    last_opp = opp[-1]
    if last_opp == 'D':
        if last_me == 'D':
            return 'D'
        if rng.random() < 0.3:
            return 'C'
        return 'D'
    if opp_c * 100 < n * 45:
        return 'D'
    if rng.random() < 0.08:
        return 'D'
    return 'C'
